INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love Match Tennis', 'Lover Match Tennis is a tennis game where you play as a first-year tennis girl who gets to challenge one of three seniors: Maiko a junior, Kumiko a second year, and finally Jun-Kun a third year is the toughest out of the other two. You must knock the ball in because if it''s out then the opponent gets the points, or you can still earn points depending on how long you prevent the ball from going out. The game ends when your opponent gets all 4 wins.' FROM games WHERE igdb_id = 56712 ON CONFLICT (game_id, language_code) DO NOTHING;
