INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Melody Master', 'Melody Master is a fantastic cartridge that, when used in conjunction with your Vectrex light pen, introduces you to the exciting world of music. It allows you to compose your own melodies and even has the capability to play flute and piano harmony with rhythm sections of snare and cymbals. 
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41988 AND ge.slug = 'music' ON CONFLICT DO NOTHING;
