INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cylon Attack', 'Cylon Attack is a pseudo 3D space shooter played from a first-person perspective and clearly based on the American TV series Battlestar Galactica where the Cylon race is featured, but not carrying an official license. The player is the only interceptor pilot on an Earth supply mothership. He has to survive the different attack waves of the enemies while defending the ship. At the start of each wave he is launched in a fighter ship and needs to destroy all enemies to survive the wave, while flying around freely.' FROM games WHERE igdb_id = 261992 ON CONFLICT (game_id, language_code) DO NOTHING;
