INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blockade Runner', 'A 3D shoot ''em up. You have to guide a fleet of four merchant space freighters to Earth with vital supplies. Hostile aliens have sighted you and forced you enter a dangerous asteroid belt. And now, you must try to avoid these asteroids, to destroy the Robot mines and alien space ships and also contend with fuel shortages and prevent the deflector shields from over-heating.' FROM games WHERE igdb_id = 23864 ON CONFLICT (game_id, language_code) DO NOTHING;
