INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mah Jong', 'Mah Jong is a game based on the popular Chinese table game of the same name. It was released by Nintendo for the Famicom and Famicom Disk System, and was one of the earliest titles for both systems. The game allows for two players to play at once, which is two less than the regular Mahjong game. The game was released for the NES in Hong Kong only, featuring an English manual.' FROM games WHERE igdb_id = 16610 ON CONFLICT (game_id, language_code) DO NOTHING;
