INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pogo Joe', 'Pogo Joe is a computer game for the Commodore 64 and Atari 8-bit family, written by William F. Denman, Jr. and Oliver Steele. Michael Haire did the artwork, and Steven Baumrucker wrote the sound and music subroutines, designed and named the levels, and wrote the music. It was published by Screenplay in 1983.
