INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hiyoko Fighter', 'In Hiyoko Fighter you control a little chick who must collect eggs dropped by chickens while being chased by snakes. It takes a couple of cues from Pac-Man as it has tunnels you can walk into to warp to another part of the screen when you’re feeling trapped. There are 3 eggs laid by the chickens, a white one that gives you points, a red one enables temporary invincibility and the ability to kill the green snakes, and a yellow egg will advance you to the next level.' FROM games WHERE igdb_id = 224856 ON CONFLICT (game_id, language_code) DO NOTHING;
