INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mountain King', 'Deep inside a long-lost diamond mine is the secret Temple Chamber of a forgotten civilization. There, a priceless Golden Crown sits high on a pedestal, vulnerable to plundering explorers seeking to control its power. but this treasure is jealously guarded by the denizens of the mountain, and whoever has the daring and courage to challenge them, seize the Crown, and escape to the mountaintop with it will become MOUNTAIN KING!' FROM games WHERE igdb_id = 12315 ON CONFLICT (game_id, language_code) DO NOTHING;
