INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roc ''N Rope', 'Your player is a mountain climber who must avoid cavemen, dinosaurs and pterodactyls as he climbs up the cliff-sides. Your goal in each level is to climb up and reach a mystical bird with great plumage, while staying one step above the bonus timer which determines how long you may stay on each level.
