INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Portopia Serial Murder Case', 'An investigation adventure in which the player, acting as an unnamed Japanese detective, is called to solve the murder of a bank executive by searching for clues, exploring different areas, interacting with characters, and solving item-based puzzles. The game, especially its Famicom version, was received positively in Japan, where it was an influential title that defined the visual novel genre, as well as inspiring future designers such as Hideo Kojima and paving the way for creator Yuji Horii to go on to make Dragon Quest series of role-playing games.' FROM games WHERE igdb_id = 48358 ON CONFLICT (game_id, language_code) DO NOTHING;
