INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Dungeons of Moria', 'The Dungeons of Moria, or just Moria, is a roguelike computer game inspired by J. R. R. Tolkien''s novel The Lord of the Rings. The game''s objective is to kill a Balrog, presumably Durin''s Bane, deep within the Mines of Moria. A later port of Moria called Umoria (UNIX Moria) inspired the Angband roguelike game. This game influenced the preliminary design of Blizzard Entertainment''s Diablo.' FROM games WHERE igdb_id = 139345 ON CONFLICT (game_id, language_code) DO NOTHING;
