INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Bros.', 'Mario Bros. is a title for the Game & Watch. Despite its name, it has no similarity to the arcade game Mario Bros. Instead of plumbing, Mario and Luigi are working at a bottling factory and must prepare packages of bottles to load onto a delivery truck. This game, played on the Multi Screen model of the Game & Watch, a few months before the much more popular arcade title, making it the first game to feature Luigi.' FROM games WHERE igdb_id = 131939 ON CONFLICT (game_id, language_code) DO NOTHING;
