INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Reach for the Stars', 'Reach for the Stars is a space strategy game where players manage their own civilization in a 2D galaxy. Players compete against up to three AI opponents, focusing on economic management, planetary development, fleet construction, and technological advancement. The game emphasizes strategic planning and resource allocation over diplomacy or tactical combat, with customizable game parameters allowing players to modify the core mechanics to their preferences.' FROM games WHERE igdb_id = 10034 ON CONFLICT (game_id, language_code) DO NOTHING;
