INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Planetfall', 'Planetfall is a sci-fi business trading game where the players command their own merchant fleet. They can travel between the different planetary systems (with changing business conditions), buy and sell any of the six available resources (uranium, iron ore, machinery, medical supplies, computers, and gems), make money and make deposits in banks. A game can have a maximum of 15 star systems.' FROM games WHERE igdb_id = 262513 ON CONFLICT (game_id, language_code) DO NOTHING;
