INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pacmania', 41014, '1983-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8gph.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sch403.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pacmania', 'Not to be confused with Pac-Mania by Namco, this is a Pac-Man clone where the object is to eat dots and power pills. Several ghosts appear in their hideout at the center of the maze, and these ghosts will eventually make their way through the maze, chasing Pac-Man wherever he goes. However, eating the power pills cause the ghosts to turn blue, allowing Pac-Man to hunt a ghost down and then eat it for bonus points, which are also awarded for eating a fruit that appears somewhere within the maze. Warp tunnels are located at either side of the screen, and these can be used to get away from ghosts that are on Pac-Man''s tail.
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 41014 AND ge.slug = 'arcade' ON CONFLICT DO NOTHING;
