INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Libble Rabble', 'Libble Rabble is an arcade game that was released by Namco in October 1983. It was designed by Toru Iwatani, who had also designed the Gee Bee series, Pac-Man, and Pole Position. It is a curious but challenging game, where the player tries to harvest little mushrooms (Mushlins) while avoiding various enemies, and was the first game from Namco to use a Motorola 68000 processor (which ran at 6.144 MHz).
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 37945 AND ge.slug = 'puzzle' ON CONFLICT DO NOTHING;
