INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mad-martha', 45367, '1983-12-31', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mad Martha', 'This (mostly) text adventure game places you in the role of hen-pecked hero, Henry Littlefellow. Seeking entertainment once in his life, your goal is to steal back your wages from your wife''s purse and head off to the bright lights of the nearby casino (and other establishments) for a night of fun. Unfortunately, your axe-wielding maniac wife won''t let things be that simple, and even escaping the house will be tricky without stumbling in the dark or waking the baby and alerting her to your sneaky plan.
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 45367 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
