INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcadia', 'In this highly addictive top-down arcade shoot-em-up from 1982, originally for the ZX Spectrum, defend yourself from wave upon wave of deadly alien combatants using your Ion Thrust Drive and dual Plasma Disruptors.' FROM games WHERE igdb_id = 202654 ON CONFLICT (game_id, language_code) DO NOTHING;
