INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heist', 'Heist is a single screen platform game where the player takes control of a bank manager who''s task it is to return all the money bags to the vault at the base floor. The bank consists of a number of floors connected with ladders and the money bags are scattered all around it. There is a problem though, as four burglars have made it into the bank and are now trying to catch the player so that they can get away with the cash.' FROM games WHERE igdb_id = 348043 ON CONFLICT (game_id, language_code) DO NOTHING;
