INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Honeybug', 'The player helps protect a beehive by defending it from weevils, placing different bees, and killing runaway larva. At the beginning of a level, the player is given the number of grubs and honey cells they''re required to fill to complete the level. The player fills sections of nest and honeycomb.' FROM games WHERE igdb_id = 347826 ON CONFLICT (game_id, language_code) DO NOTHING;
