INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fruity Freddy', 'Freddy''s job is to pick all the fruit in Mr. Meano''s back garden without being killed. The planted seeds grow up into flowers which eventually produce fruit. The player completes a level if they pick all the fruit, but if a piece of fruit becomes too ripe it explodes, spreading four more seeds onto the screen. If Mr. Meano sees the player pick a plant before it bears fruit he will emerge from his house and chase the player.' FROM games WHERE igdb_id = 347833 ON CONFLICT (game_id, language_code) DO NOTHING;
