INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Funfair', 'The player controls a gun that moves horizontally at the side of the screen, while trying to hit a series of horizontally-moving targets. The goal on each level is to clear the screen of ducks, rabbits, and teddy bears. The player has a limited number of bullets each level, so must shoot carefully.' FROM games WHERE igdb_id = 348041 ON CONFLICT (game_id, language_code) DO NOTHING;
