INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Heist', 'As a cat burglar, it''s up to you to collect all of the valuable paintings from each level while avoiding security systems, pits and robotic sentries which move back and forth. Each level is comprised of three floors and ladders connecting them. Your cat burglar has only the ability to jump, and you must rely entirely on that to keep you alive.' FROM games WHERE igdb_id = 24018 ON CONFLICT (game_id, language_code) DO NOTHING;
