INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('subterranea', 24435, '1983-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/yv6kcdqmiuowwiuyc9pg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr3t1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Subterranea', 'Subterranea is Imagic''s entry into the Defender category. Subterranea''s gameplay is broken into two types of screens. The first is a side view dogfight between your ship and some hapless enemies that are trying to home in on it. Things heat up in the second (and far more common) type of screen, which consists of Defender-style action minus the humanoids. You''re required to shoot a specific number of aliens, then pass through a gate to the next stage.
