INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('godzilla', 7744, '1983-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6amz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/gwl2ezfakvoaz8irmp19.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Godzilla', 'Godzilla is a strategy game in which you must command the military in an attempt to kill Godzilla before he destroys Tokyo. If Godzilla reaches Tokyo, the game is over. The game is a large grid on the map of Japan and nearby waters. There are 25 grids (7 of which contain Japan and one containing Tokyo.) Godzilla is randomly set in any of the 25 grids except the grid with Tokyo. The player has a choice of attacking Godzilla or moving troops. You are given a choice of attacking with a land attack, sea attack, air attack, a missile or an atom bomb. When choosing an air, land or sea attack you must choose how many troops, boats or jets you want to send out (you can only send out how many of the given attackers are in the grid that Godzilla is.) You can also move troops and boats to different grids as opposed to attacks. After an attack it will show the amount of attackers killed and how effective the attack was. (e.g. If you send out a sea attack it will tell how many boats were sunk.) After this Godzilla will move to another grid. If Godzilla is on land he will go on a rampage and it will show how many civilians were killed. The atom bomb is the most powerful weapon in the game. Whenever it is used it will destroy all life and weapons around the surrounding 8 squares. If the bomb goes off near Tokyo, the game is over.' FROM games WHERE igdb_id = 7744 ON CONFLICT (game_id, language_code) DO NOTHING;
