INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cuthbert in the Jungle', 'Poor Cuthbert is in trouble again. He failed to overcome the Moronians (See Cuthbert Goes Walkabout and Cuthbert Goes Digging), so he has been sent to the jungle, where his troubles are many. He must fight his way through the jungle collecting treasures, jumping pits and swinging across alligators whilst being aware of the killer scorpion in the basement. High speed arcade action game. Full colour graphics. Machine Code. Joystick required.' FROM games WHERE igdb_id = 114769 ON CONFLICT (game_id, language_code) DO NOTHING;
