INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bomb Ace', 'Your headquarters has received a report of enemy tanks rolling towards the border...a massive deployment, an entire armed cavalry ready to attack your city and destroy its buildings. Your only chance is to dispatch your bombers and destroy the tanks and the enemy factory. A game of high-stakes precision bombing runs against a powerful enemy.' FROM games WHERE igdb_id = 362431 ON CONFLICT (game_id, language_code) DO NOTHING;
