INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hobo', 'Hobo was developed and published by Emerson Radio Corp., which was released in 1983. This is essentially a Frogger clone, albeit the road is diagonal and you play a bum/hobo instead of a frog.' FROM games WHERE igdb_id = 281193 ON CONFLICT (game_id, language_code) DO NOTHING;
