INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomytronic 3D: Thundering Turbo', 'The Tomytronic 3D is a series of portable, handheld gaming devices released by Takara Tomy Co., Ltd. The device featured a strap so the player would be able to wear it around the neck in-between playing. The Tomytronic simulated 3D by having two LCD panels that were lit by external light through a window on top of the device. Released in 1983, it was the first dedicated home video 3D hardware.
