INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('van-van-car', 38556, '1983-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co80kd.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Van-Van Car', 'Van-Van Car is an arcade game that was released by Sanritsu, in 1983, and licensed to Karateco for EU manufacture and distribution; as with Dream Shopper and Dr. Micro, it runs on Namco''s Pac-Man hardware (a Zilog Z80, running at 3.072 MHz), but with two Texas Instruments SN-76496s running at 1.78975 MHz for sound. The flyer may give the impression that it uses an isometric perspective but it uses the same overhead view as the first six Pac-Man titles - and, the player must use a 4-directional joystick to take control of a yellow racer car (the eponymous "Van-Van Car"), which is on a mission to burst balloons with its front-mounted spike while watching out for the three "killer" cars (which are red, green, and blue, so the last one looks somewhat like an evil version of the car from Namco''s Rally-X).
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 38556 AND p.igdb_id = 52 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tropical-trouble', 18589, '1983-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1pgy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zv6rakttmjcrdvbqqnse.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tropical Trouble', 'Clumsy Clarence is vacationing on a tropical island with his girlfriend Doris. Unfortunately, their vacation is interrupted when Doris is kidnapped by the bully Beach Bruiser. Now Clarence needs to rescue Doris by chasing the Beach Bruiser all over the island! The Beach Bruiser will be carrying Doris to the right and the screen scrolls to follow. You need guide Clarence and catch up to Doris. There are many obstacles on the screen which temporarily slow down your progress. Coconuts, ferns, clams, sand snakes, and lava will all appear in your way. If you get slowed down too much and hit the left side of the screen, you lose one of your lives. From time to time, Doris will drop a handkerchief; collect this and you become temporarily invincible! If you catch Doris, you then move on to the next section of the island; when each section of the island has been completed you then need to battle the Beach Bruiser on a bridge. If you''re successful, the game will then repeat at a more difficult skill level.' FROM games WHERE igdb_id = 18589 ON CONFLICT (game_id, language_code) DO NOTHING;
