INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvin''s Maze', 'Marvin''s Maze is a maze game where the player fight against Robonoids while trying to clear the maze of dots. There are two ways to finish each rack: eating up all the dots, or destroying a certain number of Robonoids (listed at the bottom of the screen). Two ways to destroy the Robonoids: shoot them, or remove the ground from under them at certain points of the maze.' FROM games WHERE igdb_id = 24631 ON CONFLICT (game_id, language_code) DO NOTHING;
