INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yellow Submarine', 'Yellow Submarine was a prototype coded by an unknown Atari programmer to demonstrate directional control and the ability to move off one side of the screen and reappear on the opposite side. The Beatles yellow submarine graphic was not used in any Atari 5200 video game and was perhaps nothing more than an inspiration by the original programmer. There is no game here only the ability to control the yellow submarine on and around the screen' FROM games WHERE igdb_id = 46916 ON CONFLICT (game_id, language_code) DO NOTHING;
