INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Robot II', 'Mr Robot II is the sequel to Mr Robot and His Robot Factory, a platform game created for 8-bit Atari computers by Ron Rosen and released in 1983. The game is about collecting the 100 energy units distributed on the screen.' FROM games WHERE igdb_id = 378845 ON CONFLICT (game_id, language_code) DO NOTHING;
