INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Advanced Dungeons & Dragons: Treasure of Tarmin', 'In Treasure of Tarmin the player wanders through a multi-tiered dungeon, each level consisting of a maze and its surrounding hallway. The objective is to slay the Minotaur who guards the Treasure of Tarmin and take his treasure.' FROM games WHERE igdb_id = 5655 ON CONFLICT (game_id, language_code) DO NOTHING;
