INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('space-shuttle-a-journey-into-space', 12318, '1983-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ym5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bp1rmo9krxqzj9ju5q6p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Shuttle: A Journey Into Space', 'Space Shuttle is a simulation game where you are the pilot of space shuttle Discovery. Your goal is to launch the Discovery, establish an orbit around the Earth, open the cargo bay doors and recover a satellite to perform repairs, and finally land the Discovery successfully, all while using as little fuel as possible. Each time the complete mission is accomplished, it will then repeat at a higher difficulty level (in the higher difficulty levels the satellite has a more erratic flight path). The game is played from a first person perspective in the space shuttle cockpit where you can control everything from the shuttles engines to cargo bay doors. When the game is over you will be given a ranking which is based on the number of successful dockings and the amount of fuel that was used.' FROM games WHERE igdb_id = 12318 ON CONFLICT (game_id, language_code) DO NOTHING;
