INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cavelon', 'In this horizontally-scrolling maze game, You the heroic knight must reach the top floor of Castle Cavelon, rescue a fair maiden and do battle with the Black Wizard! Armed with bow and arrow and a magic sword, you must avoid or kill the castle security guards while collecting the 8 pieces of the exit door that are scattered around the corridors, in order to proceed to the next floor.' FROM games WHERE igdb_id = 40971 ON CONFLICT (game_id, language_code) DO NOTHING;
