INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brad Blasts the Galactic Barbarians', 'The year is 2052. Earth-headquarters of the Intergalactic Security Network - is under threat of war. Can Special Space Service agent Brad Stevens locate and destroy the Galactic Brabarian''s super power serum? The odds are a million to one against him on this maximum security mission!' FROM games WHERE igdb_id = 301528 ON CONFLICT (game_id, language_code) DO NOTHING;
