INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tooth Protectors', 'In this game the player must prevent objects dropping from the top of the screen from reaching the bottom by positioning their character directly under the falling objects. The player''s character is a small smiling face carrying a strand of dental floss above its head. They must prevent the snack squares from reaching the row of white teeth along the bottom of the screen; repeated hits by the snacks cause the teeth to blink and disappear from tooth decay.' FROM games WHERE igdb_id = 11236 ON CONFLICT (game_id, language_code) DO NOTHING;
