INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('treasure-below', 282745, '1983-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7mpc.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Treasure Below', 'There''s fabulous golden treasure down there, just waiting to be taken. There''s also much danger with jelly fish, octopus, sharks and other undersea creatures patrolling the deep. You''ve got your trusty knife and speargun for protection. Be careful, sometimes these sea monsters will surround you and you have to fight your way to the top to keep your golden treasure along with your quest. The action gets faster and faster. You test every video skill you know, plus invent a few new ones, but get that treasure you will.' FROM games WHERE igdb_id = 282745 ON CONFLICT (game_id, language_code) DO NOTHING;
