INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Walker', 'Walker (also known as ''Clown Downtown'' or ''Schussel, der Polizistenschreck'') is an action game, developed by Starsoft and published by Quelle, which was released in Europe in 1983. The game is similar to another Atari 2600 game: Bobby is going home.' FROM games WHERE igdb_id = 282747 ON CONFLICT (game_id, language_code) DO NOTHING;
