INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dice Puzzle', 'If you enjoy games like Rubik''s Cube, then you''ll like this one. The object of Dice Puzzle is to get all 16 dice to show the same number. You accomplish this by clicking on a column or row, which advances all of the numbers in that column or row by one (of course six advances to one). See how quickly (or in how many moves) you can do it.' FROM games WHERE igdb_id = 40645 ON CONFLICT (game_id, language_code) DO NOTHING;
