INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Series Major League Baseball', 'World Series Major League Baseball is a baseball sports game that supports both ECS and Intellivoice (for play by play announcements). The game is based on real baseball player statistics (even though the names had been changed to fictional ones before the release) and offers baseball games using multiple cameras (including in-game split-screen), showing the game in a 3D display rather than side-scrolling fashion.' FROM games WHERE igdb_id = 5711 ON CONFLICT (game_id, language_code) DO NOTHING;
