INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Standing Stones', 'The Standing Stones is a dungeon crawler set in Arthurian legend, where players embark on a quest to recover The Holy Grail and Excalibur from Kormath''s underground lair. As a knight aided occasionally by Lancelot, players navigate through a 3D maze-like dungeon with grid-based movement. Character creation involves randomized stats across five traits - Virility, Intellect, Holiness, Agility, and Initial Hits. The gameplay combines exploration, treasure hunting, and random combat encounters with Kormath''s minions, which can be handled through combat, bribery, or greetings. Players can collect magic items, potions, and rest during their journey, with a save game feature available to preserve progress.' FROM games WHERE igdb_id = 24786 ON CONFLICT (game_id, language_code) DO NOTHING;
