INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Froglet', 'Froglet is a 1-player Frogger clone. The player controls a frog that moves in cardinal directions, trying to cross two busy highways with cars traveling in opposite directions. The roads are separated by a river with moving lily pads that the frog must hop across. There are six homes at the top of the screen that the player tries to position their frog into. The player starts with five lives, and the game restarts if all are used.' FROM games WHERE igdb_id = 262402 ON CONFLICT (game_id, language_code) DO NOTHING;
