INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('oink', 18580, '1983-10-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/tgyrf7xftjzu3mtgp50u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr0os.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oink!', 'Oink! is based on the fairy tale of the three little pigs. The big bad wolf is trying to blow down each of the pigs houses. You control each pig one at a time. The wolf is at the bottom of the screen and will blow a hole in the house one section at a time. Each time a hole is formed, the pig must patch it up quickly so the wolf can''t get in. New materials are located at the top of the screen, and you need to grab them and place them in the holes as they are formed. The longer you last, the tougher the wolf will become! You start the game controlling the pig whose house is made of straw; when he is caught, you move on to the pig in the house made of sticks. Finally you will control the pig in the house made of bricks. When all three pigs have been caught by the wolf, the game is over.' FROM games WHERE igdb_id = 18580 ON CONFLICT (game_id, language_code) DO NOTHING;
