INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Journey', 'Journey is an arcade game released by Bally Midway in 1983. Rock band Journey had enjoyed major success in the early 1980s, and Bally/Midway decided to ride this wave of popularity by creating an arcade game based on the group. Its release was intended to coincide with a US tour by the band.' FROM games WHERE igdb_id = 85680 ON CONFLICT (game_id, language_code) DO NOTHING;
