INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider Kong', 'Spider Kong shares very similar gameplay to Donkey Kong, where the player is required to climb ladders and avoid obstacles to get to the top. In Spider Kong, however, the enemy throwing objects at you is not an ape but a giant spider.' FROM games WHERE igdb_id = 40737 ON CONFLICT (game_id, language_code) DO NOTHING;
