INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Bugs!', 'You are in a maze in which you must get the eggs laid by the bugs, put them in a box, and exit the maze. Although you are faster than the bugs, they are intelligent and will trap you. The screens increase in difficulty. At the higher levels super bugs join the chase.' FROM games WHERE igdb_id = 248572 ON CONFLICT (game_id, language_code) DO NOTHING;
