INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barroom Baseball', 'Barroom Baseball was a prototype game coded by Atari in 1983 for use within Atari 5200 arcade machines but it was never released. The game itself is essentially RealSports Baseball modified to remove some of the game options. It was also intended to be a timed game, requiring additional coins or tokens in order to continue with the game. As with RealSports Baseball, Barroom Baseball includes steals, nine different pitch types, hit-and-run plays, synthesized speech, a detailed scoreboard, tag-ups, dirt-colored base paths, the ability to control the speed of pitches and swings of the bat, and other such bells, whistles, and necessities.' FROM games WHERE igdb_id = 46904 ON CONFLICT (game_id, language_code) DO NOTHING;
