INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Curse of Azriel', 'A superb graphic fantasy role playing/trading game. You start the game as a new captain of a merchant ship at anchor just outside the port of Aron''s Bay. Your first ship is just a coastal vessel and unsuited to the rigours of travel across the vast oceans, but make a profit from your trading around the coastal ports and you''ll soon be able to buy yourself and your men a larger, ocean-going vessel.' FROM games WHERE igdb_id = 317821 ON CONFLICT (game_id, language_code) DO NOTHING;
