INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Flip & Flop', 'Flip and Flop is an isometric platform game by Jim Nangano for First Star Software. The player controls Flip, a kangaroo, who jumps around on top of the platforms and Mitch the monkey, who hangs underneath platforms.' FROM games WHERE igdb_id = 41006 ON CONFLICT (game_id, language_code) DO NOTHING;
