INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Glob', 'Guide the insatiable Glob through corridors, up and down the elevators and through the side tunnels in his never-ending search for snacks. An assortment of crafty animals relentlessly pursue the Glob and fight him for control of the elevators. Kill them by sticking to the ceiling and dropping on them or just avoid them and munch a dozen different snacks to clear the 24 unique levels.' FROM games WHERE igdb_id = 40465 ON CONFLICT (game_id, language_code) DO NOTHING;
