INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castle Elsinore', 'In a free literary adaptation of Shakespeare''s Hamlet, Castle Elsinore offers the opportunity to explore the namesake castle from the play to collect as much treasure as possible and deposit it at the town hall of the nearby village. This is a simple text adventure, with most puzzles simply consisting of giving the right item to the right person. Two-word commands are entered to navigate through the world that contains lots of purely decorative rooms.' FROM games WHERE igdb_id = 146106 ON CONFLICT (game_id, language_code) DO NOTHING;
