INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Glib', 'Glib Video Word Game is a one or two player action game with 25 variations, designed to be played on the Atari 2600 Video Computer System. In each of 5 games, there are 5 skill levels, varied time speeds, bonus points, and automatic "arcade" scoring. Letters pulse, parade, disappear, explode. You may be quick enough to catch them but the real winner knows how to play them!' FROM games WHERE igdb_id = 40672 ON CONFLICT (game_id, language_code) DO NOTHING;
