INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jump Coaster', 'In this game, you maneuver a caped man along roller-coaster tracks, grabbing money bags and trying to save your girlfriend, all the while avoiding cops and gorillas (which either swing on the ropes and throw deadly bananas and apples at you, or ride in roller-coaster cars, intent on hitting you.) 
