INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hover Bovver', 'The lawn needs mowing and your mower doesn''t work. You look next door and see your neighbor''s lawnmower. When he''s not looking, you grab his lawnmower and start mowing your lawn. Avoid being caught as you mow the lawn while avoiding your flower beds. Your dog can help you keep the neighbor away.' FROM games WHERE igdb_id = 47174 ON CONFLICT (game_id, language_code) DO NOTHING;
