INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Horror House', 'Horror House is the very first graphical adventure game published by Nihon Falcom in 1983. The title was created by a student of Kindai University named Fujio Fujimori who had previously had several games published inside the pages of Japanese computer magazines like I/O Magazine, RAM and others at the time. Horror House would be the first in a trilogy of games released by Falcom that were classified as "occultic mystery adventure" games with Horror House Part II releasing in December and Monster House releasing the next year in 1984.' FROM games WHERE igdb_id = 230762 ON CONFLICT (game_id, language_code) DO NOTHING;
