INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Billiards', 'Aim carefully and fire a miracle shot! This game will make you feel like a hustler. Enjoy this intellectual game which allows you a glimpse into the adult world. Realistic games will be played as the seven balls bounce, roll, and collide in the most complicated manner. You can change playing conditions to match your skill.' FROM games WHERE igdb_id = 47511 ON CONFLICT (game_id, language_code) DO NOTHING;
