INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aquatron', 'Aquatron is a side-scrolling shooter in which the player controls a spaceship over a planet completely covered with water. Unfortunately the planet is under attack and in each level, the player has to kill the steadily increasing opposition. The spaceship can be turned and is able to move both over and under water.' FROM games WHERE igdb_id = 172456 ON CONFLICT (game_id, language_code) DO NOTHING;
