INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cakewalk', 18537, '1983-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ab735629inpzyffc3tyj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr3s6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cakewalk', 'You are facing six conveyor belts which are transporting cakes from the left side of the screen in your direction. You have to catch the cakes when they reach the end of their line and prevent them from dropping on the floor. Since the conveyor belts run at different speeds it sometimes happens that two cakes reach the end of their respective lines at the same time. So that you will not drop one of the two cakes you can push a button which will halt the conveyor belt of your choice for four seconds so that you can take of each cake one at a time.' FROM games WHERE igdb_id = 18537 ON CONFLICT (game_id, language_code) DO NOTHING;
