INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hey! Stop!', 'Hey! Stop! is a clone of the game Keystone Kapers, originally developed by Activision. The game is for the most part exactly the same except for a few color and sprite changes. In Hey! Stop!, you are not playing as a policeman, trying to chase down a thief but you instead play as a droid chasing down an alien (despite the fact that the box art displays a picture of the former).' FROM games WHERE igdb_id = 40735 ON CONFLICT (game_id, language_code) DO NOTHING;
