INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battle Ship Clapton II', 'In this basic, top-down shoot-em-up set in space the player can move the ship anywhere on the screen to shoot the incoming enemy ships. There are also static mines that do not attack the player but explode when collided with. As time goes on different types of enemy ship target the player and more of them to shoot.' FROM games WHERE igdb_id = 47547 ON CONFLICT (game_id, language_code) DO NOTHING;
