INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Catch Time', 'You are having dinner when a horde of animals (mostly) insects arrive and want to steal your food. Your only weapon is insecticide liquid which you can spray in two directions (up and down). This game is a rip-off of Atari 2600 game "Plaque Attack" where you are defending your teeth against food with toothpaste.' FROM games WHERE igdb_id = 40590 ON CONFLICT (game_id, language_code) DO NOTHING;
