INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Fail', 'You are in charge of keeping a mischievous old man from cutting the power lines that connect to the Hudson Soft development room. Power comes from a battery on the upper left of the screen and is represented by white characters with bolts on their heads called “Electric-Kun”. They will slowly make their way to the development room and once they reach it a programmer will churn out a program and Hudson will make some money and you’ll get points! However if they run into an area without a line they’ll disappear.' FROM games WHERE igdb_id = 224855 ON CONFLICT (game_id, language_code) DO NOTHING;
