INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Senjyo', 'The title of this game translates from Japanese as ''Battlefield''. The simple gameplay involves the player controlling a fixed turret on a tank shooting oncoming alien enemies through a cross-hair target. A certain number of enemies must be destroyed to progress to the next stage. The original arcade cabinet was a cocktail table.' FROM games WHERE igdb_id = 40018 ON CONFLICT (game_id, language_code) DO NOTHING;
