INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Party Mix', 'Call some friends and mix it up with five wild and crazy games: Bop a Buggy, Tug of War, Wizards'' Keep, Down on the Line, and Handcar. Go head-to-head, or in teams of two. Compete against people, not a cold computer. Everyone plays at once.' FROM games WHERE igdb_id = 40660 ON CONFLICT (game_id, language_code) DO NOTHING;
