INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Motocross', 'Motocross is a bike racing game for one player against the clock, one player against the computer, or two players. Included are three different racetracks of varying lengths, each with many twists, turns, and even some jumps. Be careful when racing, or you could skid off the track on a sharp turn or crash after a poorly timed jump! You can also use the track editor to create your own track to race on. For each race, you can choose anywhere from one to ten laps to be completed.' FROM games WHERE igdb_id = 270254 ON CONFLICT (game_id, language_code) DO NOTHING;
