INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('time-warp', 40597, '1983-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9a48.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Warp', 'This game has you placed in a spacecraft of some kind (the cover art makes it look like a futuristic passenger jetliner with weapons attached, but I don''t know honestly!) flying through what looks like a cave, while taking on several enemies that attack you from the right side of the screen. After surviving a few rounds, you''ll go into an ''underground'' cave where you fly through a treacherous corridor and attempt to dock with a refueling station (I''d guess.) After that, it''s back to blasting targets again. Lather, rinse, repeat.' FROM games WHERE igdb_id = 40597 ON CONFLICT (game_id, language_code) DO NOTHING;
