INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Biotek', 'The game takes place inside a bacteria factory. You walk around and spray the various bacteria with yeast. That will turn them into white happy cloud-like bacteria. If you spray them again they will turn malevolent, so make sure not to overdo it! Move all the happy bacteria to the little bottle to clear the stage.' FROM games WHERE igdb_id = 141392 ON CONFLICT (game_id, language_code) DO NOTHING;
