INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boogie Woogi Jungle', 'Boogie Woogi Jungle is an action game, where your character must collect a number of objects scattered around each screen before the timer runs out. Most of the objects are on ledges, requiring climbing up ladders and across rope bridges. Other characters are also running around the screen, and must be avoided to prevent losing a life. Graphically and game-play wise, it is very similar to Lode Runner, except that instead of digging holes to temporarily trap your pursuers, you can fire either horizontally or vertically to stun them.' FROM games WHERE igdb_id = 202347 ON CONFLICT (game_id, language_code) DO NOTHING;
