INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danger Ranger', 'Another winner from Kenneth Kalish (Author of Phantom Slayer, Escape and Invader''s Revenge). Danger Ranger must collect ten keys from the Chamber of Pasha, whilst warding off the Floating Urns, Radioactive Bats and Roving Eyes. Then he must face the Acid Chamber to collect all the Treasure Chests, avoiding not only the drops of acid, but shooting the four demons which guard the chamber. Five Levels of Play. Sound Effects. High speed arcade action game. Full colour graphics. Machine code. Joystick Required.' FROM games WHERE igdb_id = 114679 ON CONFLICT (game_id, language_code) DO NOTHING;
