INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('marine-battle', 277530, '1983-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7e6n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvyvg.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marine Battle', 'Marine Battle is an arcade shooter which pits your destroyer against a multitude of aerial and naval forces. Your ship can move back and forth across the top of the water, and can fire directly upwards at planes or downwards at submarines or the elusive ghost ship whose shadowy presence occasionally manifests itself at the bottom of the screen. Both planes and submarines may fire back at you, and the goal for a given level is to destroy a certain number of submarines before a timer runs out and while avoiding incoming fire.
