INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fall of Rome', 'The Fall of Rome is a strategy game set in 395 BC where the Roman Empire was starting to lose it''s grip from Barbarians and armies around Europe, the Middle East and North Africa. You have the chance to save the Empire by fighting off attacks or attacking your enemies around your various provinces over 12 turns. Each turn represents five years and is split into three phases, Income and Expenditure, Movement and finally Combat.' FROM games WHERE igdb_id = 262401 ON CONFLICT (game_id, language_code) DO NOTHING;
