INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Gladiator', 'The Last Gladiator is an early Apple 2 game published by Electronic Arts. It involves playing through 8 levels of combat as a Gladiator killing monsters in an arena. Each level changes focus by providing weapons including a pistol, club, pitchfork, spear, and boomerang.' FROM games WHERE igdb_id = 24502 ON CONFLICT (game_id, language_code) DO NOTHING;
