INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinball', 'Pinball is a Multi Screen Game & Watch game released in December of 1983. Nintendo manufactured around 250,000 units of the game worldwide. It''s basically just a portable pinball game where you control two flippers. The goal is to keep the ball above the flippers by hitting it. The ball will then go in a fairly random direction and hit the bumpers, thus giving the player points. The model number for the game was PB-59, with PB standing for Pinball.' FROM games WHERE igdb_id = 145219 ON CONFLICT (game_id, language_code) DO NOTHING;
