INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boing!', 'A bouncing cute-pie of a hero who is controlled by joystick as he leaps with dizzying speed across parallel rows of panels. The object: hit each panel in sequence, changing their color and finishing them off, while avoiding the nasty, bouncing Bubble Eater, or the jumping Pin, which move like greased lightning across the field.' FROM games WHERE igdb_id = 11141 ON CONFLICT (game_id, language_code) DO NOTHING;
