INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boggy ''84', 'You are a man who must collect a set of keys on a level with several floors. You can jump between floors using springboards, which gives you an advantage over your enemies, who must use ladders to climb between floors. You must also use those in order to decend to a lower floor. Later levels add touches such as a ski slope you must ascend while avoiding the enemies. Hitting them from below will put them out of action.' FROM games WHERE igdb_id = 40261 ON CONFLICT (game_id, language_code) DO NOTHING;
