INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('chase-the-chuck-wagon', 40628, '1983-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/viyzhnranipz6dcd9pjb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mmjkuqxapvvil6kk4zdr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chase the Chuck Wagon', 'In the 80''s, the popular commercial for Purina dog food included a dog chasing a tiny chuckwagon across the kitchen floor. Inspired by this, Chase the Chuckwagon was produced by Spectravision and released as a promotional item from the Ralston Purina Company. Buy lots of dog food and you could own this. The simple rarity of this game combined with its historical coolness makes it one of the "holy grail" games. The object is to navigate the dog through a maze in an effort to reach the chuckwagon, while avoiding the dog catcher and other obstacles. If he makes it, an animation shows the dog chasing after the chuckwagon and stopping to eat the dog food that falls out of it.' FROM games WHERE igdb_id = 40628 ON CONFLICT (game_id, language_code) DO NOTHING;
