INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('crackpots', 23843, '1983-05-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/khyok43rplaxo40njwrr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lcucmhffylpgcxlvmmxj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crackpots', 'We''re infested! A bug barrage is swarming out of the sewer, chomping away at every building in town. Entire neighborhoods are now crumb piles! Over in Brooklyn, Potsy, the rooftop gardener, is defeating his beloved building with his only weapon - potted petunias. Be a good neighbor. Help him take potshots at the insect invaders... Quick! When too many bugs crawl into the windows, they''ll start eating you out of house and home!' FROM games WHERE igdb_id = 23843 ON CONFLICT (game_id, language_code) DO NOTHING;
