INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Car Race', 'Car Race is a simple racing game. The objective of the game is to race on a single track, evading other cars and collecting fuel on the ground. The longer the player can last, the higher the score.' FROM games WHERE igdb_id = 276913 ON CONFLICT (game_id, language_code) DO NOTHING;
