INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raft Rider', 'White water everywhere! And hidden in the strong current are any number of dangers lying in wait to capsize your log raft. Your mission is to make your way downstream as far as possible, avoiding treacherous rocks, feisty moose, and sections of tree which have been cut down by a pesky beaver. Skillful maneuvering is not without rewards, however, because there are also gold nuggets appearing in the river, which, when touched, can be accumulated to extend your trek into the wilderness.' FROM games WHERE igdb_id = 22819 ON CONFLICT (game_id, language_code) DO NOTHING;
