INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mangia''', 'Your mother has been cooking all day preparing your favorite pasta dish, but then nothing is too good for her favorite! Now, it''s only fair that you put a smile on her face, a gleam in her eyes, and a glow in her heart. How? How else! Eat! Eat! - Mangia! Mangia! Come on, it''s good for you!' FROM games WHERE igdb_id = 24495 ON CONFLICT (game_id, language_code) DO NOTHING;
