INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dog Fight', 'Enemy fighters arrive, wave after wave, attempting to outflank the player’s fighter jet and trap it in the path of their fire. The player can only move the jet side to side to avoid incoming fire and attempt to line up a shot on the enemy fighters. Each new wave of enemies brings new tactics, new weapons to evade… and a new batch of targets.' FROM games WHERE igdb_id = 39768 ON CONFLICT (game_id, language_code) DO NOTHING;
