INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Robot and His Robot Factory', 'Mr. Robot and His Robot Factory is a single-player platform game created for the Atari 8-bit family by Ron Rosen and ported to the Apple II and Commodore 64. The music for the Atari 8-bit version is by Gary Gilbertson (using Philip Price''s Advanced Music Processor) and published in 1984 by Datamost. Robert McNally performed the Apple II translation.[2]
