INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('save-new-york', 23209, '1983-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/p2rpqe3ecotwbzbf3u4b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scr735.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Save New York', '"Save New York" is a shooter where the action takes place on one screen only; but there are lots of things going on on that screen. You see blue sky over skyscrapers and subway tunnels beneath. New York is under attack, and you are a pilot in a little blue airplane who must save it from destruction caused by aliens. At the beginning of each stage, the aliens begin to drop from the sky. Your goal is to cruise around in your plane and to shoot them, preferably before they descend on a building, because then they will begin to crush it until it is destroyed completely. Once you have disposed of such an alien wave, you enter the next stage, with tougher and more numerous foes. Your plane might run out of fuel; in this case, you must pick up fuel left by friendly planes who appear sometimes on the screen. Often an alien will lay an egg on the ground, and a newly born baby will immediately begin to destroy the buildings from below. To prevent this, you will have to leave your craft, enter the dangerous subway tunnels, and dispose of the young alien using your handgun.' FROM games WHERE igdb_id = 23209 ON CONFLICT (game_id, language_code) DO NOTHING;
