INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lifeboat', 'Lifeboat is a multi-screen Game & Watch video game released in 1983. Nintendo produced an estimated 500,000 units worldwide. The model number for the game was TC-58. In the game, you''ll have to maneuver two lifeboats and catch people who are jumping out of a ship on fire. The game was held similarly to how you would hold a book.' FROM games WHERE igdb_id = 145218 ON CONFLICT (game_id, language_code) DO NOTHING;
