INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tropical-angel', 39940, '1983-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/uojtxzh3e6rzev9ubkil.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/g5okwjp6xiabattmppk4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tropical Angel', 'An abstract take on the 3d racing genre, Tropical Angel puts the player in control of a female water-skier who must dodge the many rocks that protrude from the water while attempting to steer through a set number of gates - in the form of a pair of flags - before the time limit expires. The acceleration button needs to be held down all the time while the ''trick'' button makes the water-skiing girl spin through one-eighty degrees and proceed to ski backwards. The player cannot steer while traveling backwards, but will earn bonus points for the duration of the trick. As the game progresses, small ramps, buoys and sharks come into play. The small ramps can be jumped to add to the player''s score, although they''re always in difficult to reach locations. The buoys are usually very close together, but skiing between them earns bonus points. Finally, the shark will appear from time-to-time, running into it means game over, regardless of how much time the player has left.' FROM games WHERE igdb_id = 39940 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 39940 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
