INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('seiken-densetsu', 297610, '1983-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8319.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scrx3j.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seiken Densetsu', 'The protagonist of Seiken Densetsu must explore dangerous wilderness in a fantasy land in order to locate and obtain four sacred swords, which allegedly grant immortality to whoever manages to possess them. This Japanese-made role-playing game is heavily influenced by early Ultima installments, having a nearly identical visual style, interface, and gameplay system. The protagonist explores an overhead world map, visiting towns where weapons, armor, items and food can be bought. Food rations are necessary to have for preventing the hero from starving. Experience points and gold are obtained from defeating enemies. Interaction is performed by pressing keys corresponding to commands, such as Move, Question, Enter, etc.' FROM games WHERE igdb_id = 297610 ON CONFLICT (game_id, language_code) DO NOTHING;
