INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamikaze Saucers', 'Your ship can move left or right but it does not move in a smooth scrolling fashion. Rather, it moves into one of several preset positions. When your ships is in the center of the screen, it fires directly upwards. As it moves towards the left or right, the firing angle adjusts accordingly with the aim point being the top middle of the screen.' FROM games WHERE igdb_id = 40733 ON CONFLICT (game_id, language_code) DO NOTHING;
