INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Jong', 'A mahjong puzzle-action game with sliding block and maze elements. Players control Mr. Jong to make mahjong hands by pushing tiles into a pit at the top of the screen while also avoiding ogres in pursuit. Mr. Jong can temporarily defeat the ogres by crushing them with shoved tiles (similar to Pengo), or by collecting a special power tile and tagging an ogre (similar to Pac-Man).' FROM games WHERE igdb_id = 329415 ON CONFLICT (game_id, language_code) DO NOTHING;
