INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cookie Monster Munch', 'It''s fun! Ten different game levels challenge, entertain and reward children! Game levels progress from simple, noncompetitive games for younger children to fast and dynamic games for the older child. It''s educational! COOKIE MONSTER MUNCH helps children practice pre-reading skills and encourages learning through play.' FROM games WHERE igdb_id = 40587 ON CONFLICT (game_id, language_code) DO NOTHING;
