INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Music Construction Set', 'Compose and play a musical score using an easy graphical interface and toolkit. Use a pointer to drag notes, sharps, and other music nomenclature directly onto a staff, then play your creation. You can cut, copy, and paste entire sections of music, as well as print your masterpiece.' FROM games WHERE igdb_id = 57587 ON CONFLICT (game_id, language_code) DO NOTHING;
