INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3-Demon', '3-Demon is a Pacman game in 3D. You have to go through a maze, collect dots and avoid the enemies. After having cleaned the level of a certain percentage of dots, you have the option to move to another level immediately by pressing the down key, where the enemies are smarter and move faster.' FROM games WHERE igdb_id = 14470 ON CONFLICT (game_id, language_code) DO NOTHING;
