INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ice Trek', 'In order to stop another Ice Age from occurring, Vail the Avenger must make a trek across the frozen lands in order to reach the Ice Palace of Kalktron the Terrible and put a stop to his evil plans to freeze the land. He will have to ski through a herd of Caribou, cross the frozen river, and then take on the many dangers of the Ice Palace in order to stop Kalktron. Can he stop another Ice Age?' FROM games WHERE igdb_id = 18590 ON CONFLICT (game_id, language_code) DO NOTHING;
