INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('robot-tank', 18675, '1983-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3grx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scrcxd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robot Tank', 'There are numerous enemy tanks crossing the countryside, destroying everything in their path! Your job is to command a robot tank to stop them. Robot Tank is a first person perspective arcade style action game. There are twelve squadrons of tanks to destroy, each containing twelve tanks. Each time you destroy a complete squadron, you earn an extra reserve tank before moving on to the next, more difficult squadron. The game takes place twenty four hours a day; gameplay will alternate from early morning to mid afternoon to late at night. In addition to the constantly changing time of day, the weather can also change unexpectedly. Snow, rain, and fog will appear occasionally making it tougher to spot your targets. Luckily your tank is equipped with radar to help locate the enemy when visibility is poor. As your tank takes damage you will lose some capabilites, such as speed, the radar, or your canons. If your tank takes too much damage, it will be destroyed; the game ends when all of your reserve tanks are gone.' FROM games WHERE igdb_id = 18675 ON CONFLICT (game_id, language_code) DO NOTHING;
