INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pressure Cooker', 'Business is booming at "The Grille". Hamburger orders are just pouring in. But back in the Assembly Room, the Food Dispenser is pouring out condiments everywhere. Help Short-Order Sam fill each order with the proper combination of tomatoes, onions, lettuce and cheese. And don''t forget the bun! Then, rush the completed orders to the Wrapping Room fast. Alright cooks, grab your spatulas!' FROM games WHERE igdb_id = 25732 ON CONFLICT (game_id, language_code) DO NOTHING;
