INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pandemonia', 'Pandemonia is an arcade platform game developed by CRL Group PLC in 1983. The game is set in the year 2000, where planet Earth has been invaded by alien beings who control their domain from the top of the world''s largest skyscraper. The player''s task is to destroy the alien headquarters located in the skyscraper. The game features several challenging levels and gameplay mechanics.' FROM games WHERE igdb_id = 317530 ON CONFLICT (game_id, language_code) DO NOTHING;
