INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One on One: Dr. J vs. Larry Bird', 'One on One: Dr. J vs Larry Bird features basketball legends Julius Erving and Larry Bird competing in head-to-head matchups at a single basket court. Players can engage in timed matches or play to a target score, utilizing offensive moves like rotations, jump shots, and slam dunks, while defending through steals and blocks. The game includes signature moves from both athletes, slow-motion replays of notable plays, and a unique feature where players can shatter the backboard - prompting a frustrated janitor to clean up the debris before play can resume.' FROM games WHERE igdb_id = 69833 ON CONFLICT (game_id, language_code) DO NOTHING;
