INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gamma-Attack', 'You are the commander of the only GAMMA ship in this stellar field. The Vegan war fleet has taken control of your GAMMA outpost planet and is defending it with Vegan laser pulse tanks. This planet is the only inhabitable planet in this star system, and you must stay there and fight the Vegans as long as you can.' FROM games WHERE igdb_id = 40667 ON CONFLICT (game_id, language_code) DO NOTHING;
