INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Swordquest: Fireworld', 'Swordquest is an unfinished series of video games produced by Atari, Inc. in the 1980s as part of a contest, consisting of three finished games and a planned but never released fourth game. All of the games came with a comic book that explained the plot, as well as containing part of the solution to a major puzzle that had to be solved to win the contest. Fireworld was the second of the four games. Its room structure was based on the tree of life.' FROM games WHERE igdb_id = 17015 ON CONFLICT (game_id, language_code) DO NOTHING;
